-- ========================================================
-- SINKRONISASI DATA RKP & RKPD APBD 35.10 (POIN 1.c.1)
-- Wilayah: 35.10 (Kabupaten Banyuwangi)
-- ========================================================

CREATE TABLE IF NOT EXISTS `dukungan_kpu_apbd` (
  `Id` int(11) NOT NULL AUTO_INCREMENT,
  `KodeWilayah` varchar(50) NOT NULL,
  `PrioritasId` int(11) NOT NULL,
  `NamaPrioritas` text DEFAULT NULL,
  `KegiatanId` int(11) DEFAULT NULL,
  `NamaKpu` text DEFAULT NULL,
  `KodeSubKegiatan` varchar(100) DEFAULT NULL,
  `NamaSubKegiatan` text DEFAULT NULL,
  `PaguAnggaran` varchar(100) DEFAULT NULL,
  `NilaiKeselarasan` decimal(5,2) DEFAULT 100.00,
  `Keterangan` text DEFAULT NULL,
  `Dokumen` varchar(255) DEFAULT NULL,
  `Halaman` varchar(50) DEFAULT NULL,
  `Tabel` varchar(100) DEFAULT NULL,
  `Catatan` text DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`Id`),
  KEY `idx_wilayah` (`KodeWilayah`),
  KEY `idx_prioritas` (`PrioritasId`),
  KEY `idx_kegiatan` (`KegiatanId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DELETE FROM `dukungan_kpu_apbd` WHERE `KodeWilayah` = '35.10';

